-- Disposable local database only; synthetic reservations. Never run in production.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(21);
SELECT extensions.ok(NOT has_function_privilege('anon','public.claim_pelecard_test_init(uuid)','EXECUTE'),'anonymous cannot claim');
SELECT extensions.ok(NOT has_function_privilege('authenticated','public.claim_pelecard_test_init(uuid)','EXECUTE'),'browser cannot claim');
SELECT extensions.ok(NOT has_function_privilege('service_role','public.claim_pelecard_test_init(uuid)','EXECUTE'),'general API role cannot dispatch');
SELECT extensions.ok(has_function_privilege('pelecard_test_init_adapter','public.claim_pelecard_test_init(uuid)','EXECUTE'),'adapter has narrow claim privilege');
SELECT extensions.ok(NOT has_table_privilege('pelecard_test_init_adapter','public.pelecard_test_payments','UPDATE'),'adapter cannot directly change TEST state');
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM unnest(ARRAY['orders','sales','payment_transactions','accounting_events','accounting_documents']) t WHERE has_table_privilege('pelecard_test_init_adapter','public.'||t,'SELECT,INSERT,UPDATE,DELETE')),'adapter has no commercial privileges');
INSERT INTO auth.users(id,email) VALUES ('72000000-0000-4000-8000-000000000001','adapter@example.test');
INSERT INTO public.pelecard_test_payments(id,created_by) VALUES ('72000000-0000-4000-8000-000000000002','72000000-0000-4000-8000-000000000001');
SELECT extensions.is((SELECT count(*) FROM public.claim_pelecard_test_init('72000000-0000-4000-8000-000000000002')),0::bigint,'old reservations cannot dispatch');
SELECT extensions.throws_ok($$UPDATE public.pelecard_test_payments SET init_transport='node_v1'$$,'23514','test_identity_immutable','cannot convert old attempt');
SELECT extensions.lives_ok($$UPDATE public.pelecard_test_payments SET init_quarantined_at=now(),init_quarantine_reason='Provider session unknown; permanently abandoned without redispatch' WHERE id='72000000-0000-4000-8000-000000000002'$$,'old uncertain attempt can be permanently quarantined');
SELECT extensions.throws_ok($$UPDATE public.pelecard_test_payments SET init_quarantined_at=NULL,init_quarantine_reason=NULL WHERE id='72000000-0000-4000-8000-000000000002'$$,'23514','test_quarantined','cannot undo quarantine');
SELECT extensions.throws_ok($$UPDATE public.pelecard_test_payments SET status='pending',redirect_url='https://example.test',confirmation_key='synthetic' WHERE id='72000000-0000-4000-8000-000000000002'$$,'23514','test_quarantined','quarantined attempt can never progress');
SELECT extensions.is((SELECT count(*) FROM public.claim_pelecard_test_init('72000000-0000-4000-8000-000000000002')),0::bigint,'quarantined attempt cannot dispatch');
INSERT INTO public.pelecard_test_payments(id,created_by,init_transport) VALUES ('72000000-0000-4000-8000-000000000003','72000000-0000-4000-8000-000000000001','node_v1');
SELECT extensions.throws_ok($$UPDATE public.pelecard_test_payments SET status='pending',redirect_url='https://example.test',confirmation_key='synthetic' WHERE init_transport='node_v1'$$,'23514','test_dispatch_required','node reservation requires dispatch claim');
SELECT extensions.is((SELECT amount_minor FROM public.claim_pelecard_test_init('72000000-0000-4000-8000-000000000003')),100,'claim returns server amount');
SELECT extensions.is((SELECT count(*) FROM public.claim_pelecard_test_init('72000000-0000-4000-8000-000000000003')),0::bigint,'second claim fails closed');
SELECT extensions.throws_ok($$UPDATE public.pelecard_test_payments SET init_dispatch_started_at=NULL WHERE init_transport='node_v1'$$,'23514','invalid_test_dispatch','cannot reset claim');
SELECT extensions.is((SELECT status FROM public.pelecard_test_payments WHERE init_transport='node_v1'),'initiating','claim cannot establish payment success');
INSERT INTO public.pelecard_test_payments(id,created_by,init_transport,created_at) VALUES ('72000000-0000-4000-8000-000000000004','72000000-0000-4000-8000-000000000001','node_v1',now()-interval '3 minutes');
SELECT extensions.is((SELECT count(*) FROM public.claim_pelecard_test_init('72000000-0000-4000-8000-000000000004')),0::bigint,'expired reservations cannot dispatch');
SELECT extensions.lives_ok($$UPDATE public.pelecard_test_payments SET status='pending',redirect_url='https://gateway20.pelecard.biz/PaymentGW/synthetic',confirmation_key='synthetic' WHERE id='72000000-0000-4000-8000-000000000003'$$,'claimed reservation keeps normal TEST initialization transition');
SELECT extensions.lives_ok($$UPDATE public.pelecard_test_payments SET status='test_verified',provider_transaction_id='synthetic-node-transaction',api_status='000',transaction_status='000',verified_at=now() WHERE id='72000000-0000-4000-8000-000000000003'$$,'authoritative verification keeps normal TEST transition');
SELECT extensions.is((SELECT count(*) FROM public.claim_pelecard_test_init('72000000-0000-4000-8000-000000000003')),0::bigint,'verified TEST cannot dispatch again');
SELECT * FROM extensions.finish();
ROLLBACK;
